pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes memory data) public {
        vm.assume(adr != address(0) && adr != address(c));
        // Fund contract
        vm.deal(address(c), 2 ether);
        // Record owner's balance before Command
        address owner = c.Owner();
        uint256 ownerBalBefore = owner.balance;
        uint256 contractBalBefore = address(c).balance;
        // Execute Command with small value that triggers no refund
        vm.prank(owner);
        c.Command{value: 0.1 ether}(adr, data);
        uint256 contractBalAfter = address(c).balance;
        // After Command, the owner's balance minus the decrease in contract balance must be constant
        uint256 ownerBalAfter = owner.balance;
        // Rule: owner.balance + (contract.balance change) = constant (negliging gas)
        // More precisely: (ownerBalAfter - ownerBalBefore) == (contractBalBefore - contractBalAfter)
        assertTrue(ownerBalAfter - ownerBalBefore == contractBalBefore - contractBalAfter);
    }
}

