pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, bytes memory data, uint256 value) public {
        vm.assume(caller != address(0));
        vm.assume(data.length <= 256);
        value = bound(value, 0, 10 ether);

        // Setup: ensure Owner has some balance to withdraw (via receive)
        vm.deal(address(c), 1 ether);

        // Call Command with arbitrary data and value
        vm.prank(c.Owner());
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSelector(c.Command.selector, address(0), data));
        vm.assume(success); // filter reverts from arbitrary calls

        // Get state after Command
        uint256 contractBalance = address(c).balance;

        // The rule: Owner's balance (msg.sender in withdraw) after Command cannot be less than what withdraw would send in reference
        // In reference, withdraw sends contractBalance (full balance). In bug, it sends contractBalance - 1 ether.
        // So after any Command, the Owner should still be able to receive at least contractBalance - 1 ether.
        // But we can't call withdraw here because it would change state. Instead, use the fact that Owner is the caller.
        // The invariant: after Command, the difference between Owner's balance and contractBalance must be >= -1 ether
        // (since bug might shortchange owner by 1 ether)

        // Actually simpler: check that the contract balance is not less than 0 (always true) and use a property:
        // In reference, if we could call withdraw now, Owner would get contractBalance.
        // In bug, Owner would get contractBalance - 1 ether. So a discrepancy of 1 ether is expected.
        // Thus the rule: contractBalance >= 0 (trivially true) – but we need something that fails on bug.
        // Better: The bug only manifests when withdraw is called. So we must call withdraw and compare.

        // Let's call withdraw now (after Command) and check the owner's final balance
        uint256 ownerBefore = c.Owner().balance;
        vm.prank(c.Owner());
        c.withdraw();
        uint256 ownerAfter = c.Owner().balance;

        // In reference: ownerAfter = ownerBefore + contractBalance (since full balance sent)
        // In bug: ownerAfter = ownerBefore + (contractBalance - 1 ether)
        // So the difference should equal the contract balance before withdraw in reference, but less in bug.
        // Rule: ownerAfter - ownerBefore should equal contractBalance (the full balance) in reference.
        // That holds for all inputs in reference (since withdraw sends all). In bug, it's off by 1 ether.

        assertTrue(ownerAfter - ownerBefore == contractBalance, "Owner should receive full contract balance");
    }
}

